CREATE TABLE IF NOT EXISTS ai.company_context_drafts (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, status text NOT NULL, revision integer NOT NULL, result_jsonb jsonb NOT NULL, source_fingerprints_jsonb jsonb NOT NULL DEFAULT '[]'::jsonb, provenance_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, review_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS company_context_drafts_scope_idx ON ai.company_context_drafts (tenant_id, company_id, updated_at DESC);
